```
Integer queryMaxAnalyzedOffset = fieldContext.field.fieldOptions().maxAnalyzedOffset();
if ((queryMaxAnalyzedOffset !=null) && (queryMaxAnalyzedOffset == -1)) {
     queryMaxAnalyzedOffset = maxAnalyzedOffset;
}
